import{z as p,x as B,o as t,c as s,q as e,j as i,D as r,d as o,s as n,S as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"价格-时间对 pro-rata","description":"","frontmatter":{"title":"价格-时间对 pro-rata","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/price-time-pro-rata.md","filePath":"quant/price-time-pro-rata.md","lastUpdated":1791063341000}'),A={name:"quant/price-time-pro-rata.md"};function d(F,a,c,m,u,D){const E=B("Mermaid");return t(),s("div",null,[a[2]||(a[2]=e('<h1 id="价格-时间对-pro-rata" tabindex="-1">价格-时间对 pro-rata <a class="header-anchor" href="#价格-时间对-pro-rata" aria-label="Permalink to &quot;价格-时间对 pro-rata&quot;">​</a></h1><div class="epigraph"><p>同一价位上先到先得，会把竞争赶到速度与占位；按剩余量比例分配，会把竞争赶到订单尺寸。优先规则改的是排队博弈的策略空间，不是簿的几何画法。</p><footer>—— 据 Harris, Trading and Exchanges 对优先权的论述；对照 Cordella and Foucault, Minimum Price Variations, Time Priority and Quote Dynamics, Journal of Financial and Quantitative Analysis, 1999</footer></div><p><a href="/quant/optimal-limit-placement">最优放置</a>默认价格优先再时间优先（price-time / FIFO）。缺口是另一常见规则：同一价位按尺寸比例分配（pro-rata），期货与部分利率产品常用。Cordella 与 Foucault（1999）已说明时间优先与 tick 如何共同决定报价动态。本课比较两种规则下的占位、尺寸与速度激励，不重画两侧价量阶梯。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>FIFO 下，队尾的边际执行概率低，交易者要么提前占位，要么提高一个 tick 买新队头，要么改市价。速度的价值是到达次序。pro-rata 下，后到的大单仍能分到一刀，尺寸成为份额，「排队」不再是严格的名次。激励变成：在最优价上挂尽可能大的量，甚至超过真实意愿，成交后再撤余量。问题是规则如何改变：(i) 谁提供近端深度；(ii) 撤单与虚报尺寸；(iii) 小单是否被挤出。</p><p>Harris 把优先权当作市场设计的一等对象。本课是这一等对象的理论比较，具体期货匹配算法留到市场设计单元。</p><p><span class="marginnote">数字实例：市价买单 100 手，BBO 上有先到的 A 300 手和后到的 B 100 手。FIFO：A 全部成交、B 一手没份；pro-rata：按剩余量占比，A 得 75 手、B 得 25 手。同样一笔单，规则一换，「先后」就不再决定一切。</span></p>',7)),(t(),i(l,null,{default:r(()=>[n(E,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20MO%5B%22%E5%B8%82%E4%BB%B7%E5%8D%95%E5%90%83%E5%85%A5%20q%EF%BC%8C%E5%88%B0%E8%BE%BE%E6%9C%80%E4%BC%98%E4%BB%B7%22%5D%20--%3E%20SPLIT%7B%22%E5%90%8C%E4%BB%B7%E4%BD%8D%E6%8C%89%E5%93%AA%E6%9D%A1%E8%A7%84%E5%88%99%E5%88%86%E9%85%8D%22%7D%0A%20%20SPLIT%20--%3E%7C%22FIFO%22%7C%20F%5B%22%E4%BB%8E%E9%98%9F%E5%A4%B4%E4%BE%9D%E6%AC%A1%E8%80%97%E5%B0%BD%22%5D%0A%20%20SPLIT%20--%3E%7C%22pro-rata%22%7C%20P%5B%22%E6%8C%89%E5%90%84%E5%8D%95%E5%89%A9%E4%BD%99%E9%87%8F%E5%8D%A0%E6%AF%94%E5%88%86%E9%85%8D%22%5D%0A%20%20F%20--%3E%20F2%5B%22%E5%90%8E%E5%88%B0%E7%9A%84%E5%A4%A7%E5%8D%95%E5%8F%AF%E8%83%BD%E4%B8%80%E6%89%8B%E6%9C%AA%E5%BE%97%22%5D%0A%20%20P%20--%3E%20P2%5B%22%E5%90%8E%E5%88%B0%E7%9A%84%E5%A4%A7%E5%8D%95%E4%BB%8D%E5%88%86%E5%88%B0%E4%BB%BD%E9%A2%9D%22%5D%0A%20%20F2%20--%3E%20INC%5B%22%E6%BF%80%E5%8A%B1%EF%BC%9A%E6%8A%A2%E5%8D%A0%E4%BD%8D%E4%B8%8E%E9%80%9F%E5%BA%A6%22%5D%0A%20%20P2%20--%3E%20INCP%5B%22%E6%BF%80%E5%8A%B1%EF%BC%9A%E5%A0%86%E5%A4%A7%E5%B1%95%E7%A4%BA%E9%87%8F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<h3 id="混合规则" tabindex="-1">混合规则 <a class="header-anchor" href="#混合规则" aria-label="Permalink to &quot;混合规则&quot;">​</a></h3><p>实务常是 FIFO + 顶层比例、或做市商保证配额再 FIFO。混合把两种博弈叠在一起：先抢配额，再抢时间。理论比较先看纯规则的极端，再理解混合为何出现——保护小单或指定做市商。</p><p><span class="marginnote">时间优先在连续时间极限里变成速度竞赛：谁的线短谁当队头。这是 Budish 等人的起点。pro-rata 并不消灭速度，因为更快仍能在分配窗口内更新尺寸，但一阶武器从次序变成量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在同一 Parlour 式状态上改成交匹配。FIFO：吃 \\(q\\) 从队头依次耗尽。pro-rata：吃 \\(q\\) 按各订单剩余量占比分配，常有最小分配单位。均衡策略：FIFO 下最优是中等尺寸、早到、少虚报；pro-rata 下最优尺寸膨胀，真实需求被「展示量」掩盖。被捡风险在 pro-rata 上更尖锐：虚报的大量在信息跳时来不及全撤，可能被按比例打中。</p><p>比较静态：tick 越粗，同一价位堆积越严重，规则差异越大。tick 极细时价格优先已把量打散到许多格，同价位规则不那么关键——与 Cordella–Foucault 的 tick–时间优先互动一致。</p><h3 id="对最优放置的改写" tabindex="-1">对最优放置的改写 <a class="header-anchor" href="#对最优放置的改写" aria-label="Permalink to &quot;对最优放置的改写&quot;">​</a></h3><p>FIFO：贵一 tick 抢队头常常值得。pro-rata：贵一 tick 可能把自己放到一个更空、但仍按比例的新价位，份额高但价格更差；或留在拥挤的 BBO 用尺寸换份额。放置的 \\(k\\) 选择因此翻转，不能把 FIFO 校准的档位策略搬到国债期货上。</p>',8)),(t(),i(l,null,{default:r(()=>[n(E,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20FIFO%5B%22%E4%BB%B7%E6%A0%BC-%E6%97%B6%E9%97%B4%3A%20%E5%90%8D%E6%AC%A1%22%5D%20--%3E%20Spd%5B%22%E7%AB%9E%E4%BA%89%E9%80%9F%E5%BA%A6%E4%B8%8E%E5%8D%A0%E4%BD%8D%22%5D%0A%20%20PR%5B%22pro-rata%3A%20%E4%BB%BD%E9%A2%9D%22%5D%20--%3E%20Sz%5B%22%E7%AB%9E%E4%BA%89%E5%B1%95%E7%A4%BA%E5%B0%BA%E5%AF%B8%22%5D%0A%20%20Spd%20--%3E%20Deep%5B%22%E8%BF%91%E7%AB%AF%E6%B7%B1%E5%BA%A6%E7%9A%84%E7%BB%84%E6%88%90%22%5D%0A%20%20Sz%20--%3E%20Deep%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>优先规则分配的是即时性租金。FIFO 把租金给先到者，鼓励常设挂单（Grossman–Miller 的在场）和低延迟。pro-rata 把租金给大单，鼓励做市商用资本堆量，小的限价单预期份额低，可能改走市价，限价比例下降。经验上利率期货近端极厚，与 pro-rata 堆量一致；美股股票近端相对薄、速度竞争更明显，与 FIFO 一致。当然还有产品本身的 tick 与用户结构。</p><p><span class="marginnote">术语翻译：「即时性租金」是急着成交的人多付的那部分钱，规则决定它分给谁：FIFO 把它整块给队头，像先到先得的限量商品；pro-rata 把它按在场量摊给所有人，像按持股比例分红的合作社。</span></p><p>虚报尺寸是 pro-rata 的阴暗面：展示深度不是真实可成交意愿。隐藏与冰山在 FIFO 上主要损失时间优先；在 pro-rata 上隐藏会直接损失份额，激励更弱。规则与隐藏是一对设计，不能分开选。</p><p><span class="marginnote">常见误区：以为簿上第一档的每一手都真心想成交。按块头分蛋糕，就有人吹胀自己——pro-rata 下挂远超意愿的量抢份额、成交前再撤是真实存在的策略，所以期货簿的「厚」要打折读。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>分配的最小单位、是否允许超出需求的挂单、撤单速度限制，都会改变 pro-rata 博弈。监管若限制「明显超过意向」的挂单，堆量策略受限。跨市场 FIFO 与 pro-rata 并存时，同一宏观信息会在两个场所留下不同的扫簿形态。本课不讨论具体交易所参数表。</p><p><span class="marginnote">看见期货簿「第一档上万手」不要用股票 FIFO 的直觉读成无限流动性。比例分配下你的市价单会同时打到许多挂单，但下一瞬大量撤余，深度是一次性的。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FIFO 让竞争落在到达次序与跳价抢队；pro-rata 让竞争落在展示尺寸。</li><li>规则改变最优放置、虚报激励与小单是否愿意挂限价。</li><li>tick 越粗，同价位规则越重要。</li><li>出处：Harris, <em>Trading and Exchanges</em>；Cordella and Foucault, <em>Journal of Financial and Quantitative Analysis</em>, 1999；排队基准见 Parlour, 1998。</li></ul>',10))])}const C=p(A,[["render",d]]);export{_ as __pageData,C as default};
